void describe(int day) {
    switch (day) {
        case 6:
            printf("Weekend\n");
        case 7:
            printf("Weekend\n");
            break;
        default:
            printf("Weekday\n");
    }
}

def dedupe(items):
    result = []
    for x in items:
        if x not in result:
            result.append(x)
    return result

def mystery(n):
    count = 0
    while n:
        n &= (n - 1)
        count += 1
    return count
